package com.primehr.succession;
import com.primehr.integration.administrative.PermissionDataScope;import com.primehr.learningdevelopment.completion.infrastructure.LdCompletionCaseRepository;import com.primehr.learningdevelopment.plan.domain.*;import com.primehr.learningdevelopment.plan.infrastructure.*;import com.primehr.shared.audit.PrimeHrAuditService;import com.primehr.succession.api.SuccessionDevelopmentDtos.*;import com.primehr.succession.application.SuccessionDevelopmentServiceImpl;import com.primehr.succession.domain.*;import com.primehr.succession.infrastructure.*;import org.junit.jupiter.api.Test;import org.springframework.security.access.AccessDeniedException;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class SuccessionDevelopmentServiceTest{
 private final SuccessionDevelopmentPlanRepository plans=mock(SuccessionDevelopmentPlanRepository.class);private final SuccessionDevelopmentSourceRepository sources=mock(SuccessionDevelopmentSourceRepository.class);private final SuccessionDevelopmentMilestoneRepository milestones=mock(SuccessionDevelopmentMilestoneRepository.class);private final SuccessionDevelopmentReviewRepository reviews=mock(SuccessionDevelopmentReviewRepository.class);private final SuccessionPoolMembershipEventRepository events=mock(SuccessionPoolMembershipEventRepository.class);private final SuccessionPoolDecisionRepository decisions=mock(SuccessionPoolDecisionRepository.class);private final SuccessionCandidateRepository candidates=mock(SuccessionCandidateRepository.class);private final SuccessionReadinessPanelAssignmentRepository assignments=mock(SuccessionReadinessPanelAssignmentRepository.class);private final LdIndividualDevelopmentPlanRepository idps=mock(LdIndividualDevelopmentPlanRepository.class);private final LdIndividualDevelopmentPlanItemRepository items=mock(LdIndividualDevelopmentPlanItemRepository.class);private final LdCompletionCaseRepository completions=mock(LdCompletionCaseRepository.class);private final PrimeHrAuditService audit=mock(PrimeHrAuditService.class);private final SuccessionDevelopmentServiceImpl service=new SuccessionDevelopmentServiceImpl(plans,sources,milestones,reviews,events,decisions,candidates,assignments,idps,items,completions,audit);
 @Test void candidateOwnViewHidesRestrictedFeedbackReviewAndMembershipRationale(){var p=plan();when(plans.findByIdAndAgencyId("plan","A")).thenReturn(Optional.of(p));var m=mock(SuccessionDevelopmentMilestone.class);when(m.getStatus()).thenReturn(SuccessionDevelopmentMilestone.Status.IN_PROGRESS);when(m.getRestrictedFeedback()).thenReturn("restricted milestone");when(m.getTitle()).thenReturn("Milestone");when(m.getMeasurableOutcome()).thenReturn("Outcome");when(m.getDueDate()).thenReturn(LocalDate.of(2027,3,1));when(milestones.findByAgencyIdAndPlanIdOrderByDisplayOrder("A","plan")).thenReturn(List.of(m));var r=mock(SuccessionDevelopmentReview.class);when(r.getRecommendation()).thenReturn(SuccessionDevelopmentReview.Recommendation.CONTINUE);when(r.getEmployeeVisibleSummary()).thenReturn("Visible");when(r.getRestrictedRationale()).thenReturn("restricted review");when(reviews.findByAgencyIdAndPlanIdOrderByReviewSequence("A","plan")).thenReturn(List.of(r));var e=mock(SuccessionPoolMembershipEvent.class);when(e.getEventType()).thenReturn(SuccessionPoolMembershipEvent.EventType.ACTIVATED);when(e.getResultingStatus()).thenReturn(SuccessionPoolMembershipEvent.ResultingStatus.ACTIVE);when(e.getEmployeeVisibleReason()).thenReturn("Visible membership");when(e.getRestrictedRationale()).thenReturn("restricted membership");when(events.findByAgencyIdAndPoolDecisionIdOrderByEventSequence("A","decision")).thenReturn(List.of(e));var out=service.get("A","plan","EMP-1",PermissionDataScope.AGENCY_WIDE);assertThat(out.milestones().get(0).restrictedFeedback()).isNull();assertThat(out.reviews().get(0).restrictedRationale()).isNull();assertThat(out.membershipHistory().get(0).restrictedRationale()).isNull();}
 @Test void approvedIdpItemFromAnotherEmployeeCannotBeLinked(){var p=plan();when(plans.findByIdAndAgencyId("plan","A")).thenReturn(Optional.of(p));var item=mock(LdIndividualDevelopmentPlanItem.class);when(item.getPlanId()).thenReturn("idp");when(items.findByIdAndAgencyId("item","A")).thenReturn(Optional.of(item));var idp=mock(LdIndividualDevelopmentPlan.class);when(idp.getStatus()).thenReturn(LdIndividualDevelopmentPlan.Status.APPROVED);when(idp.getEmployeeNo()).thenReturn("EMP-2");when(idps.findByIdAndAgencyId("idp","A")).thenReturn(Optional.of(idp));assertThatThrownBy(()->service.addSource("A","plan",new SourceInput(0L,SuccessionDevelopmentSource.SourceType.APPROVED_IDP_ITEM,"item"),"PANEL",PermissionDataScope.AGENCY_WIDE,null)).isInstanceOf(AccessDeniedException.class).hasMessageContaining("another employee");}
 @Test void removalRequiresLatestPeriodicReviewRecommendation(){var p=plan();when(plans.findByIdAndAgencyId("plan","A")).thenReturn(Optional.of(p));when(reviews.findByAgencyIdAndPlanIdOrderByReviewSequence("A","plan")).thenReturn(List.of());var input=new MembershipInput(0L,SuccessionPoolMembershipEvent.EventType.REMOVED,LocalDate.of(2027,6,1),null,"Removed","Restricted");assertThatThrownBy(()->service.membership("A","plan",input,"HEAD",PermissionDataScope.AGENCY_WIDE,null)).isInstanceOf(IllegalStateException.class).hasMessageContaining("latest periodic review");}
 private SuccessionDevelopmentPlan plan(){var p=mock(SuccessionDevelopmentPlan.class);when(p.getId()).thenReturn("plan");when(p.getPoolDecisionId()).thenReturn("decision");when(p.getAssessmentId()).thenReturn("assessment");when(p.getCandidateId()).thenReturn("candidate");when(p.getEmployeeNo()).thenReturn("EMP-1");when(p.getEmployeeName()).thenReturn("Employee One");when(p.getTargetPositionName()).thenReturn("Target");when(p.getReadinessLevelCode()).thenReturn("READY");when(p.getOverallGoal()).thenReturn("Goal");when(p.getStartsOn()).thenReturn(LocalDate.of(2027,1,1));when(p.getTargetCompletionDate()).thenReturn(LocalDate.of(2027,12,31));when(p.getNextReviewOn()).thenReturn(LocalDate.of(2027,4,1));when(p.getStatus()).thenReturn(SuccessionDevelopmentPlan.Status.DRAFT);when(p.getAcknowledgmentStatus()).thenReturn(SuccessionDevelopmentPlan.AcknowledgmentStatus.PENDING);return p;}
}
